function juntarPedidosComClientes(pedidos, clientes) {
  const porId = new Map(clientes.map((cliente) => [cliente.id, cliente]))

  return pedidos.map((pedido) => ({
    ...pedido,
    clienteNome: porId.get(pedido.clienteId)?.nome ?? null,
  }))
}

