function buscarFaixa(ordenados, de, ate) {
  if (de > ate) return []

  // Busca binaria: primeiro indice com valor >= de.
  let inicio = 0
  let fim = ordenados.length

  while (inicio < fim) {
    const meio = Math.floor((inicio + fim) / 2)
    if (ordenados[meio] < de) inicio = meio + 1
    else fim = meio
  }

  const saida = []
  for (let i = inicio; i < ordenados.length && ordenados[i] <= ate; i += 1) {
    saida.push(ordenados[i])
  }

  return saida
}

function valeOtimizar({ medido, fatiaDoTempo, podeCrescer, aumentaComplexidade }) {
  if (!medido) return 'nao: sem medicao'

  const domina = fatiaDoTempo >= 0.2
  if (!domina && !podeCrescer) return 'nao: nao domina o tempo'

  return aumentaComplexidade ? 'sim' : 'sim: ganho facil'
}

