questions.solution:
function pedidosBloqueados(pedidos, bloqueados) {
  // Um Set construído uma vez troca a busca linear por consulta constante:
  // o custo cai de pedidos × bloqueados para pedidos + bloqueados.
  const bloqueadosRapido = new Set(bloqueados)

  return pedidos.filter((pedido) => bloqueadosRapido.has(pedido.clienteId)).map((pedido) => pedido.id)
}
